<include file="Publics:header"/>	<div class="mainbox">			<div class="search">				<div class="search_div">					<label>商品名称:</label>					<input name="keywords" id="keywords" type="text" placeholder="请输入商品名称"/>				</div>				<div class="search_div">					<label>关联状态:</label>					<select name="status" id="status">						<option value="0">全部</option>						<option value="1">未关联</option>						<option value="2">已关联</option>					</select>				</div>				<div class="search_div">					<label>活动时间:</label>					<input name="active_time" id="active_time" style="width: 290px" type="text" placeholder="请输入活动时间"/>				</div>				<div class="search_div">					<a id="search_goods" style="background-color: #1890ff;vertical-align: middle;padding: 6px 10px;color: #FFFFFF;cursor: pointer;text-decoration:none">搜索</a>				</div>			</div>			<div class="table-list">				<table id="goodsList" class="layui-table" lay-filter="goods">				</table>			</div>	</div><link rel="stylesheet" href="{pigcms{$static_public}layui2/css/layui.css" media="all"/><script src="{pigcms{$static_public}layui2/layui.all.js" charset="utf-8"></script><script type="text/html" id="barDemo">	{{# if(d.is_related == 0){ }}	<button class="layui-btn layui-btn-xs" lay-event="related">关联</button>	{{# }else{ }}	<button class="layui-btn layui-btn-xs" lay-event="unrelated">取消关联</button>	{{# } }}</script><script>  var goodsList = '{pigcms{:U('Adver/active_goods_list',array('id' => $id))}';  console.log(goodsList)  layui.use(['laydate','table','layer'], function(){    var laydate = layui.laydate;    var table = layui.table;    var layer = layui.layer;    let start_time = '';    let end_time = '';    //日期时间范围选择    laydate.render({      elem: '#active_time'      ,type: 'datetime'      ,range: true      ,done: function(value, date, endDate){        var time_arr = value.split(' - ')        start_time = time_arr[0]        end_time = time_arr[1]      }    });    // 搜索    $("#search_goods").click(function (){      table.reload('goodsList', {        where: {          keywords:$("#keywords").val(),          status:$("#status").val(),          start_time:start_time,          end_time:end_time,        }        ,page: {          curr: 1 //重新从第 1 页开始        }      });    });    // 列表    table.render({      elem: '#goodsList',      url: goodsList,      method:'post',      toolbar: false ,      page: true ,      where:{keywords:'',status:0,start_time:'',end_time:''},      cols: [[ //表头        {field: 'goods_name',width: 180,title: '商品名称'}        ,{field: 'mer_name',width: 120,title: '商家名称'}        ,{field: 'store_name',width: 135,title: '店铺名称'}        ,{field: 'time', title: '活动时间',width: 175,templet:function (d){            var str = '<div>' + d.start_time + ' - ' + d.end_time +'</div>';            return str;          }}        ,{field: 'status',title: '活动状态',width: 90,templet:function (d){            if(d.status == 0){              return '未开始'						}else if (d.status == 1){              return '进行中'						}else{              return '已失效'						}          }}        ,{field: 'price',width: 60, title: '原价'}        ,{field: 'act_price',width: 75, title: '活动价'}        ,{field: 'real_money',width: 86, title: '实收金额'}        ,{field: 'id', title: '操作',width: 95,toolbar: '#barDemo'}      ]],      id:'goodsList',    });    // 操作监听    table.on('tool(goods)', function (obj){      // 审核      if(obj.event == 'related'){        layer.confirm('确定关联吗？', function(index){          related(obj.data.act_goods_id,'add');          layer.close(index);        });      }else if(obj.event == 'unrelated'){        layer.confirm('确定取消关联吗？', function(index){          related(obj.data.act_goods_id,'del');          layer.close(index);        });			}    });    function related (goods_id,type){      $.post("{pigcms{:U('relateGoods',array('id' => $id))}" , {goods_id:goods_id,type:type} , function(data){        console.log(data)        if(data.status==1){          layer.msg(data.msg,{            icon: 2,              time: 2000 //2秒关闭（如果不配置，默认是3秒）          })        }else{          layer.msg(data.msg,{            icon: 1,            time: 2000 //2秒关闭（如果不配置，默认是3秒）          })          table.reload('goodsList', {            where: {              keywords:$("#keywords").val(),              status:$("#status").val(),              start_time:start_time,              end_time:end_time,            }            ,page: {              curr: 1 //重新从第 1 页开始            }          });        }      },'JSON');		}  });</script><style>	.related_goods {			margin: 10px 0;			padding: 10px 20px;			border: 1px dashed #CCCCCC;			background-color: #ffffff;      display: inline-block;	}  .table-list .summary {      margin: 10px 25px 5px 0 !important;      text-align: right !important;  }  .table-list .pager {      margin: 0 25px 5px 0 !important;      text-align: right !important;  }  .pager .next>a {      height: 30px;      line-height: 30px;  }  .pager .prev>a {      height: 30px;      line-height: 30px;  }	.search_div {			display: inline-block;			margin-left: 5px;			margin-bottom: 10px;	}	.layui-laypage-limits select {			height: 26px !important;	}</style><include file="Publics:footer"/>